/**
 * Evaluator for attribute name/value matching
 */
public static final class AttributeWithValue extends AttributeKeyPair {
    public AttributeWithValue(String key, String value) {
        super(key, value, false);
    }

    @Override
    public boolean matches(Element root, Element element) {
        return element.hasAttr(key) && value.equalsIgnoreCase(lowerCase(element.attr(key)));
    }

    @Override protected int cost() {
        return 3;
    }

    @Override
    public String toString() {
        return String.format("[%s=%s]", key, value);
    }

}

/**
 * Evaluator for attribute name != value matching
 */
public static final class AttributeWithValueNot extends AttributeKeyPair {
    public AttributeWithValueNot(String key, String value) {
        super(key, value, false);
    }

    @Override
    public boolean matches(Element root, Element element) {
        return !value.equalsIgnoreCase(lowerCase(element.attr(key)));
    }

    @Override protected int cost() {
        return 3;
    }

    @Override
    public String toString() {
        return String.format("[%s!=%s]", key, value);
    }

}

/**
 * Evaluator for attribute name/value matching (value prefix)
 */
public static final class AttributeWithValueStarting extends AttributeKeyPair {
    public AttributeWithValueStarting(String key, String value) {
        super(key, value, false);
    }

    @Override
    public boolean matches(Element root, Element element) {
        return element.hasAttr(key) && lowerCase(element.attr(key)).startsWith(value); // value is lower case already
    }

    @Override protected int cost() {
        return 4;
